const chalk = require('chalk');

function formatStatus(name, ok) {
  return ok ? chalk.green(`PASS ${name}`) : chalk.red(`FAIL ${name}`);
}

function formatSummary(passed, failed) {
  const text = `${passed} passed, ${failed} failed`;
  return failed > 0 ? chalk.bold.red(text) : chalk.bold.green(text);
}

module.exports = { formatStatus, formatSummary };
E
w $C/repo/src/banner.js <<'E'
const chalk = require('chalk');

function banner(title) {
  const line = '='.repeat(title.length);
  return [chalk.cyan(line), chalk.cyan.bold(title), chalk.cyan(line)].join('\n');
}

module.exports = { banner };
E
w $C/repo/src/stats.js <<'E'
function countResults(results) {
  const passed = results.filter((r) => r.ok).length;
  return { passed, failed: results.length - passed };
}

module.exports = { countResults };
E
w $C/repo/src/report.js <<'E'
const { banner } = require('./banner');
const { formatStatus, formatSummary } = require('./format');
const { countResults } = require('./stats');

function renderReport(title, results) {
  const { passed, failed } = countResults(results);
  return [
    banner(title),
    ...results.map((r) => formatStatus(r.name, r.ok)),
    formatSummary(passed, failed),
  ].join('\n');
}

module.exports = { renderReport };
E
