     1	import { flush, init, shutdown, trace } from 'neatlogs';
     2	
     3	type Kind = 'WORKFLOW' | 'CHAIN' | 'TOOL' | 'AGENT';
     4	type Attrs = Record<string, string | number | boolean | undefined>;
     5	
     6	let enabled = false;
     7	
     8	/** Starts tracing when NEATLOGS_API_KEY is set. Without it every helper is a plain passthrough. */
     9	export async function initTracing(workflowName = 'veritas'): Promise<boolean> {
    10	  const apiKey = process.env.NEATLOGS_API_KEY;
    11	  if (!apiKey || enabled) return enabled;
    12	  await init({ apiKey, workflowName });
    13	  enabled = true;
    14	  return enabled;
    15	}
    16	
    17	export function tracingEnabled(): boolean {
    18	  return enabled;
    19	}
    20	
    21	export async function shutdownTracing(): Promise<void> {
    22	  if (!enabled) return;
    23	  await flush();
    24	  await shutdown();
    25	  enabled = false;
    26	}
    27	
    28	/** Runs fn inside a named span. Attributes are prefixed `veritas.` so they are easy to filter on. */
    29	export async function traced<T>(name: string, kind: Kind, attrs: Attrs, fn: () => Promise<T> | T): Promise<T> {
    30	  if (!enabled) return fn();
    31	  return trace({ name, kind }, async (span) => {
    32	    for (const [k, v] of Object.entries(attrs)) {
    33	      if (v !== undefined) span.setAttribute(`veritas.${k}`, v);
    34	    }
    35	    return fn();
    36	  });
    37	}
