     3	
     4	export interface Investigation {
     5	  id: string;
     6	  repo_url: string;
     7	  commit_sha: string | null;
     8	  status: 'running' | 'awaiting_approval' | 'done' | 'failed';
     9	  current_state: string;
    10	  started_at: string;
    11	  finished_at: string | null;
    12	}
    13	
    14	export interface StepRecord {
    15	  id: number;
    16	  state: string;
    17	  name: string;
    18	  idem_key: string;
    19	  status: 'running' | 'done' | 'failed';
    20	  input_json: string | null;
    21	  output_json: string | null;
    22	  error: string | null;
    23	  started_at: string;
    24	  duration_ms: number | null;
    25	  attempt: number;
    26	}
    27	
    28	export interface StepResult<T> {
    29	  output: T;
    30	  /** True when the output came from the journal and the step body did not run. */
    31	  reused: boolean;
    32	}
    33	
    34	/** JSON with sorted object keys, so equal inputs always hash the same. */
    35	export function stableJson(value: unknown): string {
    36	  return JSON.stringify(value, (_k, v) =>
    37	    v && typeof v === 'object' && !Array.isArray(v)
    38	      ? Object.fromEntries(Object.entries(v).sort(([a], [b]) => a.localeCompare(b)))
    39	      : v,
    40	  );
    41	}
    42	
    43	export function idemKey(state: string, name: string, input: unknown): string {
    44	  return createHash('sha256').update(`${state}\n${name}\n${stableJson(input ?? null)}`).digest('hex');
    45	}
    46	
    47	/**
    48	 * Durable record of what an investigation has done. A step that finished is
    49	 * never run again for the same input: its stored output is returned instead.
    50	 */
    51	export class Journal {
    52	  constructor(private readonly db: Db) {}
    53	
    54	  createInvestigation(repoUrl: string, initialState: string): Investigation {
    55	    const id = randomUUID();
    56	    this.db
    57	      .prepare('INSERT INTO investigations (id, repo_url, current_state, started_at) VALUES (?, ?, ?, ?)')
    58	      .run(id, repoUrl, initialState, new Date().toISOString());
    59	    return this.getInvestigation(id)!;
    60	  }
    61	
    62	  getInvestigation(id: string): Investigation | undefined {
    63	    return this.db.prepare('SELECT * FROM investigations WHERE id = ?').get(id) as Investigation | undefined;
    64	  }
    65	
    66	  listInvestigations(): Investigation[] {
    67	    return this.db.prepare('SELECT * FROM investigations ORDER BY started_at DESC').all() as unknown as Investigation[];
    68	  }
    69	
    70	  setState(id: string, state: string): void {
    71	    this.db.prepare('UPDATE investigations SET current_state = ? WHERE id = ?').run(state, id);
    72	  }
    73	
    74	  setStatus(id: string, status: Investigation['status']): void {
    75	    const finished = status === 'running' ? null : new Date().toISOString();
    76	    this.db.prepare('UPDATE investigations SET status = ?, finished_at = ? WHERE id = ?').run(status, finished, id);
    77	  }
    78	
    79	  steps(id: string): StepRecord[] {
    80	    return this.db
    81	      .prepare('SELECT * FROM steps WHERE investigation_id = ? ORDER BY id')
    82	      .all(id) as unknown as StepRecord[];
    83	  }
    84	
    85	  async runStep<T>(
    86	    investigationId: string,
    87	    state: string,
    88	    name: string,
    89	    input: unknown,
    90	    fn: () => Promise<T> | T,
    91	  ): Promise<StepResult<T>> {
    92	    const key = idemKey(state, name, input);
    93	    const prior = this.db
    94	      .prepare('SELECT * FROM steps WHERE investigation_id = ? AND idem_key = ?')
    95	      .get(investigationId, key) as StepRecord | undefined;
    96	
    97	    if (prior?.status === 'done') {
    98	      return { output: JSON.parse(prior.output_json ?? 'null') as T, reused: true };
    99	    }
   100	
   101	    const startedAt = new Date().toISOString();
   102	    if (prior) {
   103	      // A step left 'running' means the process died inside it; 'failed' means it threw. Either way, run again.
   104	      this.db
   105	        .prepare("UPDATE steps SET status = 'running', error = NULL, started_at = ?, attempt = attempt + 1 WHERE id = ?")
   106	        .run(startedAt, prior.id);
   107	    } else {
   108	      this.db
   109	        .prepare(
   110	          "INSERT INTO steps (investigation_id, state, name, idem_key, status, input_json, started_at) VALUES (?, ?, ?, ?, 'running', ?, ?)",
   111	        )
   112	        .run(investigationId, state, name, key, stableJson(input ?? null), startedAt);
   113	    }
   114	
   115	    const t0 = Date.now();
   116	    const finish = this.db.prepare(
   117	      'UPDATE steps SET status = ?, output_json = ?, error = ?, duration_ms = ? WHERE investigation_id = ? AND idem_key = ?',
   118	    );
   119	    try {
   120	      const output = await fn();
   121	      finish.run('done', JSON.stringify(output ?? null), null, Date.now() - t0, investigationId, key);
   122	      return { output, reused: false };
   123	    } catch (err) {
   124	      const message = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
   125	      finish.run('failed', null, message, Date.now() - t0, investigationId, key);
   126	      throw err;
   127	    }
   128	  }
   129	}
