    19	
    20	export class Orchestrator {
    21	  private readonly journal: Journal;
    22	  private readonly limits: Limits;
    23	
    24	  constructor(private readonly opts: OrchestratorOptions) {
    25	    this.journal = new Journal(opts.db);
    26	    this.limits = opts.limits ?? loadLimits();
    27	  }
    28	
    29	  start(repoUrl: string): Investigation {
    30	    return this.journal.createInvestigation(repoUrl, 'INTAKE');
    31	  }
    32	
    33	  /**
    34	   * Drives an investigation from its recorded state until it needs approval.
    35	   * Safe to call again after a crash: finished steps are reused from the journal.
    36	   */
    37	  async run(investigationId: string): Promise<Investigation> {
    38	    const inv = this.journal.getInvestigation(investigationId);
    39	    if (!inv) throw new Error(`Unknown investigation ${investigationId}`);
    40	    if (inv.status === 'awaiting_approval' || inv.status === 'done') return inv;
    41	
    42	    this.journal.setStatus(investigationId, 'running');
    43	    const deadline = Date.now() + this.limits.investigationTimeoutMs;
    44	
    45	    return traced(
    46	      'veritas.investigation',
    47	      'WORKFLOW',
    48	      { investigation_id: investigationId, repo: inv.repo_url, resumed_from: inv.current_state },
    49	      async () => {
    50	        let state = inv.current_state as State;
    51	        try {
    52	          while (state !== 'AWAITING_APPROVAL') {
    53	            if (Date.now() > deadline) throw new InvestigationTimeout(this.limits.investigationTimeoutMs);
    54	            const next = await this.runState(inv, state);
    55	            if (!TRANSITIONS[state].includes(next)) {
    56	              throw new Error(`Illegal transition ${state} -> ${next}`);
    57	            }
    58	            this.journal.setState(investigationId, next);
    59	            state = next;
    60	          }
    61	          this.journal.setStatus(investigationId, 'awaiting_approval');
    62	        } catch (err) {
    63	          this.journal.setStatus(investigationId, 'failed');
    64	          throw err;
    65	        }
    66	        return this.journal.getInvestigation(investigationId)!;
    67	      },
    68	    );
    69	  }
    70	
    71	  private runState(inv: Investigation, state: Exclude<State, 'AWAITING_APPROVAL'>): Promise<State> {
    72	    const ctx: RunContext = {
    73	      investigationId: inv.id,
    74	      repoUrl: inv.repo_url,
    75	      db: this.opts.db,
    76	      journal: this.journal,
    77	      limits: this.limits,
    78	      step: async (name, input, fn) => {
    79	        const result = await this.journal.runStep(inv.id, state, name, input, () =>
    80	          traced(`step.${name}`, 'CHAIN', { state, step: name }, fn),
    81	        );
    82	        // A reused step still shows in the trace, marked, so skipped work is visible.
    83	        if (result.reused) await traced(`step.${name}`, 'CHAIN', { state, step: name, reused: true }, () => undefined);
