export interface HttpResponse {
  status: number;
  text: string;
}

export interface HttpOptions {
  headers?: Record<string, string>;
  retries?: number;
  timeoutMs?: number;
  /** Base delay between retries; doubled each time. */
  backoffMs?: number;
}

export type HttpGet = (url: string, opts?: HttpOptions) => Promise<HttpResponse>;

export class HttpError extends Error {
  constructor(
    readonly url: string,
    readonly status: number,
  ) {
    super(`GET ${url} returned ${status}`);
    this.name = 'HttpError';
  }
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const transient = (status: number) => status === 429 || status >= 500;

/**
 * GET with bounded retries for transient failures (network errors, 429, 5xx).
 * Other statuses are returned to the caller, which decides what a 404 means.
 */
export const httpGet: HttpGet = async (url, opts = {}) => {
  const { headers, retries = 3, timeoutMs = 30_000, backoffMs = 500 } = opts;
  let lastError: unknown;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (attempt > 0) await sleep(backoffMs * 2 ** (attempt - 1));
    try {
      const res = await fetch(url, { headers, signal: AbortSignal.timeout(timeoutMs) });
      if (transient(res.status)) {
        lastError = new HttpError(url, res.status);
        continue;
      }
      return { status: res.status, text: await res.text() };
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
};

/** GET that must succeed with JSON. */
export async function getJson(url: string, opts: HttpOptions = {}, http: HttpGet = httpGet): Promise<unknown> {
  const res = await http(url, opts);
  if (res.status !== 200) throw new HttpError(url, res.status);
  return JSON.parse(res.text);
}

/**
 * GET against the GitHub API or raw content. Sends GITHUB_TOKEN when set; if GitHub
 * rejects the token, the request is repeated without it, since these endpoints are public.
 */
export async function githubGet(url: string, http: HttpGet = httpGet): Promise<HttpResponse> {
  const base = { accept: 'application/vnd.github+json', 'user-agent': 'veritas' };
  const token = process.env.GITHUB_TOKEN;
  if (token) {
    const res = await http(url, { headers: { ...base, authorization: `Bearer ${token}` } });
    if (res.status !== 401) return res;
  }
  return http(url, { headers: base });
}

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

export interface InventoryEntry {
  name: string;
  installed: string;
  direct: boolean;
  dev: boolean;
  /** The range written in package.json, for direct dependencies. */
  spec: string | null;
}

export interface Inventory {
  projectName: string | null;
  lockfileVersion: number;
  entries: InventoryEntry[];
}

interface Manifest {
  name?: string;
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  optionalDependencies?: Record<string, string>;
}

interface Lockfile {
  lockfileVersion?: number;
  packages?: Record<string, { version?: string; dev?: boolean; link?: boolean }>;
}

const MARKER = 'node_modules/';

/**
 * Builds the dependency inventory from package.json and package-lock.json alone,
 * so nothing from the target repository is installed or executed.
 * When a package is installed at several versions, the top-level one is reported.
 */
export function parseInventory(manifest: Manifest, lock: Lockfile): Inventory {
  if (!lock.packages) {
    throw new Error(`Unsupported package-lock.json (lockfileVersion ${lock.lockfileVersion ?? 'unknown'}); version 2 or 3 is required`);
  }
  const prod = { ...manifest.optionalDependencies, ...manifest.dependencies };
  const dev = manifest.devDependencies ?? {};
  const entries = new Map<string, InventoryEntry & { depth: number }>();

  for (const [path, pkg] of Object.entries(lock.packages)) {
    if (!path.startsWith(MARKER) || !pkg.version || pkg.link) continue;
    const name = path.slice(path.lastIndexOf(MARKER) + MARKER.length);
    const depth = path.split(MARKER).length - 1;
    const seen = entries.get(name);
    if (seen && seen.depth <= depth) continue;
    const spec = prod[name] ?? dev[name] ?? null;
    entries.set(name, {
      name,
      installed: pkg.version,
      direct: depth === 1 && spec !== null,
      dev: depth === 1 && !(name in prod) && name in dev,
      spec: depth === 1 ? spec : null,
      depth,
    });
  }

  return {
    projectName: manifest.name ?? null,
    lockfileVersion: lock.lockfileVersion ?? 0,
    entries: [...entries.values()]
      .map(({ depth: _depth, ...entry }) => entry)
      .sort((a, b) => Number(b.direct) - Number(a.direct) || a.name.localeCompare(b.name)),
  };
}

export function readInventory(repoDir: string): Inventory {
  const manifestPath = join(repoDir, 'package.json');
  const lockPath = join(repoDir, 'package-lock.json');
  if (!existsSync(manifestPath)) throw new Error('No package.json at the repository root');
  if (!existsSync(lockPath)) throw new Error('No package-lock.json at the repository root; only npm projects with a lockfile are supported');
  return parseInventory(
    JSON.parse(readFileSync(manifestPath, 'utf8')) as Manifest,
    JSON.parse(readFileSync(lockPath, 'utf8')) as Lockfile,
  );
}

import semver from 'semver';
import { getJson, type HttpGet } from './http.ts';

export interface GithubRepo {
  owner: string;
  repo: string;
}

export interface MajorRelease {
  major: number;
  /** First stable version published on this major line. */
  version: string;
  publishedAt: string | null;
}

export interface PackageInfo {
  name: string;
  installed: string;
  latest: string;
  /** Deprecation message for the installed version, when the registry has one. */
  deprecated: string | null;
  repository: GithubRepo | null;
  /** Major lines after the installed version, up to and including the latest. */
  majorsCrossed: MajorRelease[];
  latestIsEsmOnly: boolean;
  latestEngines: string | null;
  sourceUrl: string;
}

interface PackumentVersion {
  deprecated?: string;
  type?: string;
  main?: string;
  exports?: unknown;
  engines?: { node?: string };
}

interface Packument {
  name?: string;
  'dist-tags'?: { latest?: string };
  versions?: Record<string, PackumentVersion>;
  time?: Record<string, string>;
  repository?: string | { url?: string };
}

export const registryUrl = (name: string) => `https://registry.npmjs.org/${name.replace('/', '%2F')}`;

/** Accepts the forms npm allows: full git URLs, `github:owner/repo`, and bare `owner/repo`. */
export function parseGithubRepo(repository: Packument['repository']): GithubRepo | null {
  const raw = typeof repository === 'string' ? repository : repository?.url;
  if (!raw) return null;
  const match =
    /github\.com[/:]([^/\s]+)\/([^/\s#]+)/.exec(raw) ?? /^(?:github:)?([\w.-]+)\/([\w.-]+)$/.exec(raw);
  if (!match?.[1] || !match[2]) return null;
  return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
}

/** A package whose latest version declares "type": "module" and offers no `require` export condition. */
function isEsmOnly(version: PackumentVersion | undefined): boolean {
  if (version?.type !== 'module') return false;
  return !JSON.stringify(version.exports ?? null).includes('"require"');
}

export function parsePackument(doc: unknown, installed: string): PackageInfo {
  const pack = doc as Packument;
  const latest = pack['dist-tags']?.latest;
  if (!pack.name || !latest || !pack.versions) throw new Error('Registry response is missing name, dist-tags.latest or versions');

  const stable = Object.keys(pack.versions)
    .filter((v) => semver.valid(v) && !semver.prerelease(v))
    .sort(semver.compare);
  const majorsCrossed: MajorRelease[] = [];
  for (const version of stable) {
    const major = semver.major(version);
    if (major <= semver.major(installed) || semver.gt(version, latest)) continue;
    if (majorsCrossed.some((m) => m.major === major)) continue;
    majorsCrossed.push({ major, version, publishedAt: pack.time?.[version] ?? null });
  }

  return {
    name: pack.name,
    installed,
    latest,
    deprecated: pack.versions[installed]?.deprecated ?? null,
    repository: parseGithubRepo(pack.repository),
    majorsCrossed,
    latestIsEsmOnly: isEsmOnly(pack.versions[latest]),
    latestEngines: pack.versions[latest]?.engines?.node ?? null,
    sourceUrl: registryUrl(pack.name),
  };
}

export async function fetchPackageInfo(name: string, installed: string, http?: HttpGet): Promise<PackageInfo> {
  return parsePackument(await getJson(registryUrl(name), {}, http), installed);
}

