38	/**
39	 * Keeps the advisories that name `pkg` and have not been withdrawn. An advisory can list
40	 * several ranges for one package, each with its own fix; the one containing `version` is used.
41	 */
42	export function parseAdvisories(json: unknown, pkg: string, version?: string): Advisory[] {
43	  if (!Array.isArray(json)) throw new Error('GitHub advisories response is not a list');
44	  const advisories: Advisory[] = [];
45	  for (const raw of json as RawAdvisory[]) {
46	    if (raw.withdrawn_at) continue;
47	    const ranges = raw.vulnerabilities?.filter((v) => v.package?.name === pkg) ?? [];
48	    const affected = (version && ranges.find((v) => inRange(version, v.vulnerable_version_range))) || ranges[0];
49	    if (!affected) continue;
50	    advisories.push({
51	      ghsaId: raw.ghsa_id,
52	      cveId: raw.cve_id ?? null,
53	      severity: toSeverity(raw.severity),
54	      summary: raw.summary ?? '',
55	      url: raw.html_url,
56	      reviewed: raw.type === 'reviewed',
...
56	export const advisoriesUrl = (pkg: string, version: string) =>
57	  `https://api.github.com/advisories?ecosystem=npm&per_page=100&affects=${encodeURIComponent(`${pkg}@${version}`)}`;
58	
59	/** Published advisories from the GitHub Advisory Database that affect `pkg` at `version`. */
60	export async function fetchAdvisories(pkg: string, version: string, http?: HttpGet): Promise<Advisory[]> {
61	  const url = advisoriesUrl(pkg, version);
62	  const res = await githubGet(url, http);
63	  if (res.status !== 200) throw new HttpError(url, res.status);
