33	/** GitHub writes ranges as ">= 4.0.0, < 4.17.21"; semver wants the comma gone. */
34	function inRange(version: string, range: string | null | undefined): boolean {
35	  return !!range && semver.satisfies(version, range.replace(/,\s*/g, ' '));
36	}
