    expect(parseCounts('# tests 3\n# pass 3\n# fail 0\n')).toEqual({ passed: 3, failed: 0 });
    expect(parseCounts('Tests:       1 failed, 7 passed, 8 total\n')).toEqual({ passed: 7, failed: 1 });
