29	/**
30	 * GET with bounded retries for transient failures (network errors, 429, 5xx).
31	 * Other statuses are returned to the caller, which decides what a 404 means.
32	 */
33	export const httpGet: HttpGet = async (url, opts = {}) => {
34	  const { headers, retries = 3, timeoutMs = 30_000, backoffMs = 500 } = opts;
35	  let lastError: unknown;
36	  for (let attempt = 0; attempt <= retries; attempt++) {
37	    if (attempt > 0) {
38	      note('retrying {url}, attempt {attempt}', { url, attempt: attempt + 1, level: 'warn' });
39	      await sleep(backoffMs * 2 ** (attempt - 1));
40	    }
41	    try {
42	      // One span per attempt, so a retry and the failure that caused it are both visible in the trace.
43	      // The body stays out of the span: a registry document can be several megabytes.
44	      let text = '';
45	      const summary = await traced('http.get', 'TOOL', { url, attempt: attempt + 1 }, async (set) => {
46	        const r = await fetch(url, { headers, signal: AbortSignal.timeout(timeoutMs) });
47	        set({ status: r.status, retry: attempt > 0 });
48	        if (transient(r.status)) throw new HttpError(url, r.status);
49	        text = await r.text();
50	        return { status: r.status, bytes: text.length };
51	      });
52	      return { status: summary.status, text };
53	    } catch (err) {
54	      lastError = err;
55	    }
56	  }
57	  throw lastError;
58	};
